contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function. Takes an address 'caller' to be approved or not,
    // and an arbitrary keepAddress to pass to logCreated. We will use this contract
    // as msg.sender when calling c, so 'caller' is used only as the address to set
    // approval for (must be an address type input as required).
    function run(address loggerToApprove, address keepAddress) public payable {
        require(loggerToApprove != address(0));
        // Initially, the logger approval status for loggerToApprove can be read
        bool before = c.approvedToLog(loggerToApprove);

        // Set approval to the opposite of whatever it was before to test both outcomes
        // Note: setApprovedLogger is onlyOwner protected. The InvMutTest contract is the deployer
        // of c (per harness), so it is the owner and can call this.
        c.setApprovedLogger(loggerToApprove, !before);

        // Read status after flip
        bool after = c.approvedToLog(loggerToApprove);

        // Now, call logCreated as this contract (msg.sender == address(this)). We need to ensure
        // we observe the relation between approvals and return value for the actual caller.
        // If loggerToApprove equals address(this), then the approval we set should affect this call.
        // Otherwise, it won't. We capture the return via low-level call to inspect success and return data.

        bool success;
        bytes memory ret;
        (success, ret) = address(c).call(abi.encodeWithSignature("logCreated(address)", keepAddress));

        // Interpret return: if call succeeded and returned a bool, decode it; otherwise consider it reverted.
        bool returnedTrue = false;
        if (success && ret.length >= 32) {
            returnedTrue = abi.decode(ret, (bool));
        }

        // General rule asserted: If this contract was approved (after flip) then the logCreated call must succeed
        // and return true; if this contract was not approved then the call must succeed and return false.
        // We express this using the observable approval for address(this) after our setApprovedLogger call
        // or before (depending on whether loggerToApprove equals address(this)).

        bool thisWasApprovedAfter;
        // If we flipped approval for loggerToApprove and it equals address(this), read the approval; else thisWasApprovedAfter remains current approval for this
        if (loggerToApprove == address(this)) {
            thisWasApprovedAfter = c.approvedToLog(address(this));
        } else {
            // We did not change approval for address(this); read its current approval state
            thisWasApprovedAfter = c.approvedToLog(address(this));
        }

        // The intended invariant: the contract's logCreated returns the approval status of msg.sender.
        // Therefore returnedTrue must equal thisWasApprovedAfter, and the call must not revert (success==true).
        assert(success && returnedTrue == thisWasApprovedAfter);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: flip approval for some address and then call logCreated
    // to ensure that logCreated's boolean return equals c.approvedToLog(address(this)).
    function run(address loggerToFlip, address keepAddress) public payable {
        require(loggerToFlip != address(0));

        // Read current approval for loggerToFlip (view call)
        bool beforeFlip = c.approvedToLog(loggerToFlip);

        // Flip approval for loggerToFlip. InvMutTest is the deployed owner of c, so this is allowed.
        c.setApprovedLogger(loggerToFlip, !beforeFlip);

        // Read approval for this contract after the flip (may be affected only if loggerToFlip == address(this))
        bool thisApproved = c.approvedToLog(address(this));

        // Call logCreated as this contract and capture whether it reverted and its returned bool.
        bool callSucceeded;
        bytes memory returnData;
        (callSucceeded, returnData) = address(c).call(abi.encodeWithSignature("logCreated(address)", keepAddress));

        bool returnedBool = false;
        if (callSucceeded && returnData.length >= 32) {
            returnedBool = abi.decode(returnData, (bool));
        }

        // Assert the general rule: the call must not revert, and its returned boolean equals c.approvedToLog(address(this)).
        // Use the previously read thisApproved to avoid calling view inside assert.
        assert(callSucceeded && returnedBool == thisApproved);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function: ensure logCreated's returned bool equals approvedToLog(address(this))
    function run(address keepAddress, address loggerToSet, bool setStatus) public payable {
        require(loggerToSet != address(0));

        // Flip/set approval for loggerToSet (state-changing call) as a top-level statement
        c.setApprovedLogger(loggerToSet, setStatus);

        // Also, ensure we can set approval for this contract itself as a top-level statement
        c.setApprovedLogger(address(this), setStatus);

        // Read the current approval for this contract via public view
        bool approved = c.approvedToLog(address(this));

        // Call logCreated as this contract (top-level state-changing call) and capture its return by direct call
        bool returned;
        returned = c.logCreated(keepAddress);

        // The general rule: the returned boolean equals the observed approval for this contract
        assert(returned == approved);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address logger, bool status) public payable {
        // logger must be non-zero to avoid trivial zero-address semantics
        require(logger != address(0));

        // Set the approval for the provided logger (state-changing top-level call)
        c.setApprovedLogger(logger, status);

        // Read the approval via the public view
        bool observed = c.approvedToLog(logger);

        // We want to check behavior when this contract acts as the caller.
        // If logger equals address(this), call logFunded directly and capture return.
        bool returned;
        bool reverted;
        if (logger == address(this)) {
            // Calling as this contract: may return true/false but should not revert according to contract logic
            reverted = false;
            try c.logFunded() returns (bool r) {
                returned = r;
            } catch {
                reverted = true;
            }
        } else {
            // If logger is some other address, we cannot make c see msg.sender==logger in this single-transaction test
            // So we only check the getter invariant for that case, and set returned == observed to form a uniform assert
            returned = observed;
            reverted = false;
        }

        // General rule: the public getter reflects the last set value, and if this contract is the logger then calling logFunded() returns that approval
        assert(observed == status && (!reverted && (logger != address(this) ? true : returned == observed)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public test function exercising setter, getter, and multiple logging calls
    function run(bool status, bytes32 b32a, bytes32 b32b, bytes32 txid) public payable {
        // No precondition on status or data; address(this) is the caller we control

        // 1) set approval for this contract
        c.setApprovedLogger(address(this), status);

        // 2) observe the public getter
        bool observed = c.approvedToLog(address(this));

        // 3) Call a variety of logging functions as this contract. Each is a top-level state-changing call.
        // We capture whether they reverted using try/catch; according to the intended contract logic they should not revert.
        bool rCreated;
        bool rGotSig;
        bool rRegistered;
        bool rFunded;
        bool rRedeemed;
        bool revertedCreated = false;
        bool revertedGotSig = false;
        bool revertedRegistered = false;
        bool revertedFunded = false;
        bool revertedRedeemed = false;

        try c.logCreated(address(0x123)) returns (bool v) { rCreated = v; } catch { revertedCreated = true; }
        try c.logGotRedemptionSignature(b32a, b32b, b32a) returns (bool v) { rGotSig = v; } catch { revertedGotSig = true; }
        try c.logRegisteredPubkey(b32a, b32b) returns (bool v) { rRegistered = v; } catch { revertedRegistered = true; }
        try c.logFunded() returns (bool v) { rFunded = v; } catch { revertedFunded = true; }
        try c.logRedeemed(txid) returns (bool v) { rRedeemed = v; } catch { revertedRedeemed = true; }

        // General rule/assertion:
        // - The public getter for this contract equals the status most recently set.
        // - None of the log* calls revert when invoked by this contract, and each returns the same boolean as the getter.
        assert(observed == status
               && revertedCreated == false
               && revertedGotSig == false
               && revertedRegistered == false
               && revertedFunded == false
               && revertedRedeemed == false
               && rCreated == observed
               && rGotSig == observed
               && rRegistered == observed
               && rFunded == observed
               && rRedeemed == observed);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public test function taking inputs to drive several logging calls
    function run(
        bool startApproved,
        address loggerToSet,
        // inputs for various log functions
        address keepAddr,
        address requester,
        bytes32 digest,
        uint256 utxoSize,
        bytes calldata redeemerOutputScript,
        uint256 requestedFee,
        bytes calldata outpoint,
        bytes32 r,
        bytes32 s,
        bytes32 pubx,
        bytes32 puby,
        bool wasFraud,
        bytes32 txid
    ) public payable {
        // precondition: the logger address we will set must be this contract (caller of c)
        // The checker deploys c and then deploys this test; msg.sender for c calls will be this contract.
        require(loggerToSet == address(this));

        // read initial approved status via public getter
        bool before = c.approvedToLog(address(this));

        // If startApproved true, setApprovedLogger to true (onlyOwner will revert unless this contract is owner).
        // To respect onlyOwner, we try/catch the setter and record whether it succeeded.
        bool setSucceeded = false;
        if (startApproved) {
            // try to call setApprovedLogger; it may revert because onlyOwner restricts it.
            try c.setApprovedLogger(address(this), true) {
                setSucceeded = true;
            } catch {
                setSucceeded = false;
            }
        }

        // Now call a variety of log functions and capture whether they reverted or returned true/false.
        bool resCreated;
        try c.logCreated(keepAddr) returns (bool v) { resCreated = v; } catch { resCreated = false; }

        bool resRedemptionRequested;
        try c.logRedemptionRequested(requester, digest, utxoSize, redeemerOutputScript, requestedFee, outpoint)
            returns (bool v) { resRedemptionRequested = v; } catch { resRedemptionRequested = false; }

        bool resGotSig;
        try c.logGotRedemptionSignature(digest, r, s) returns (bool v) { resGotSig = v; } catch { resGotSig = false; }

        bool resRegistered;
        try c.logRegisteredPubkey(pubx, puby) returns (bool v) { resRegistered = v; } catch { resRegistered = false; }

        bool resSetupFailed;
        try c.logSetupFailed() returns (bool v) { resSetupFailed = v; } catch { resSetupFailed = false; }

        bool resFraud;
        try c.logFraudDuringSetup() returns (bool v) { resFraud = v; } catch { resFraud = false; }

        bool resFunded;
        try c.logFunded() returns (bool v) { resFunded = v; } catch { resFunded = false; }

        bool resCourtesy;
        try c.logCourtesyCalled() returns (bool v) { resCourtesy = v; } catch { resCourtesy = false; }

        bool resStartedLiquidation;
        try c.logStartedLiquidation(wasFraud) returns (bool v) { resStartedLiquidation = v; } catch { resStartedLiquidation = false; }

        bool resRedeemed;
        try c.logRedeemed(txid) returns (bool v) { resRedeemed = v; } catch { resRedeemed = false; }

        bool resLiquidated;
        try c.logLiquidated() returns (bool v) { resLiquidated = v; } catch { resLiquidated = false; }

        bool resExited;
        try c.logExitedCourtesyCall() returns (bool v) { resExited = v; } catch { resExited = false; }

        // read approved status after calls
        bool after = c.approvedToLog(address(this));

        // General rule to assert:
        // - If after==true then at least one of the log calls returned true (they should succeed when approved).
        // - If after==false then none of the log calls returned true (they should fail when not approved).
        // - Additionally, approved status can only become true if setSucceeded was true; i.e., this test cannot gain approval except via successful setApprovedLogger.
        // Express as a single assert combining these facts.
        bool anySucceeded = resCreated || resRedemptionRequested || resGotSig || resRegistered || resSetupFailed || resFraud || resFunded || resCourtesy || resStartedLiquidation || resRedeemed || resLiquidated || resExited;

        assert(
            // monotonic relation: after true implies (setSucceeded || before)
            (after == (before || setSucceeded)) &&
            // when approved (after) some log call must return true
            ( !after && (anySucceeded == false) || (after && anySucceeded == true) )
        );
    }

    receive() external payable {}
}

contract InvMutTest {
