        bool resStartedLiquidation;
        try c.logStartedLiquidation(wasFraud) returns (bool v) { resStartedLiquidation = v; } catch { resStartedLiquidation = false; }

        bool resRedeemed;
        try c.logRedeemed(txid) returns (bool v) { resRedeemed = v; } catch { resRedeemed = false; }

        bool resLiquidated;
        try c.logLiquidated() returns (bool v) { resLiquidated = v; } catch { resLiquidated = false; }

