        bool resGotSig;
        try c.logGotRedemptionSignature(digest, r, s) returns (bool v) { resGotSig = v; } catch { resGotSig = false; }

        bool resRegistered;
        try c.logRegisteredPubkey(pubx, puby) returns (bool v) { resRegistered = v; } catch { resRegistered = false; }

        bool resSetupFailed;
        try c.logSetupFailed() returns (bool v) { resSetupFailed = v; } catch { resSetupFailed = false; }

        bool resFraud;
        try c.logFraudDuringSetup() returns (bool v) { resFraud = v; } catch { resFraud = false; }

        bool resFunded;
        try c.logFunded() returns (bool v) { resFunded = v; } catch { resFunded = false; }

        bool resCourtesy;
