contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property test
    function run(address loggerToSet, bytes32 digest, bytes32 r, bytes32 s, bytes32 txid, bytes32 pubx, bytes32 puby, address keep) public payable {
        require(loggerToSet != address(0));

        // Ensure we start from a fresh view: read whether this contract is approved initially
        bool initiallyApproved = c.approvedToLog(address(this));

        // If not owner, setApprovedLogger cannot be called by this contract; but constructor of c (deployer) is different
        // We try to set approved status via the public setter only if this contract is owner — but we don't know that.
        // So we exercise both branches by calling setApprovedLogger and catching revert.

        bool setSucceeded;
        // top-level state-changing call attempts to set approval for this contract
        try c.setApprovedLogger(address(this), true) {
            setSucceeded = true;
        } catch {
            setSucceeded = false;
        }

        // After attempting to set approval, read the approved status
        bool afterSetApproved = c.approvedToLog(address(this));

        // Attempt several logging calls and record whether they revert or return false/true.
        bool returnedCreated;
        bool returnedGotSig;
        bool returnedRegisteredPk;
        bool returnedRedeemed;

        // Each is a top-level call that may revert; capture revert via try/catch and otherwise capture return value
        try c.logCreated(keep) returns (bool v) { returnedCreated = v; } catch { returnedCreated = false; }
        try c.logGotRedemptionSignature(digest, r, s) returns (bool v) { returnedGotSig = v; } catch { returnedGotSig = false; }
        try c.logRegisteredPubkey(pubx, puby) returns (bool v) { returnedRegisteredPk = v; } catch { returnedRegisteredPk = false; }
        try c.logRedeemed(txid) returns (bool v) { returnedRedeemed = v; } catch { returnedRedeemed = false; }

        // Read approved status again to ensure logging calls didn't flip approval
        bool finalApproved = c.approvedToLog(address(this));

        // General rule asserted for all inputs:
        // - If afterSetApproved is true then finalApproved must be true (setting approval cannot be undone by logging calls).
        // - If afterSetApproved is false and setSucceeded is false (we weren't owner so couldn't set), then initial approval must equal final approval (logging calls cannot create approval).
        // - Additionally, whenever finalApproved is false, all log* calls must return false (or reverted, recorded as false). If finalApproved is true, those calls may return true.

        assert(
            (
                // If we successfully set approval then approval stays true
                (setSucceeded ? afterSetApproved == true && finalApproved == true : true)
            )
            &&
            (
                // If we couldn't set approval (not owner), approval didn't flip from initial to final due to log calls
                (!setSucceeded ? finalApproved == initiallyApproved : true)
            )
            &&
            (
                // If finalApproved is false then all observed log calls must be false
                (!finalApproved ? (returnedCreated == false && returnedGotSig == false && returnedRegisteredPk == false && returnedRedeemed == false) : true)
            )
        );
    }

    receive() external payable {}
}

