contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: logger address to set, desired status, and choose which logging function to call (0..4)
    // We'll call a variety of log functions that exist; pick by selectorIndex.
    function run(address logger, bool status, uint8 selectorIndex) public payable {
        require(selectorIndex <= 4);

        // Read approval before change
        bool before = c.approvedToLog(logger);

        // Change approval as the test contract (note: onlyOwner modifier in C may cause revert if caller isn't owner)
        // So we must call setApprovedLogger and catch if it reverts. The rule we assert only applies when the setter succeeded.
        bool setReverted;
        try c.setApprovedLogger(logger, status) {
            setReverted = false;
        } catch {
            setReverted = true;
        }

        // Read approval after attempted change
        bool after = c.approvedToLog(logger);

        // Now simulate calling one of the logging functions as the logger address is not possible (msg.sender is this contract).
        // But public logging functions check approvedToLog(msg.sender). So to test effect we call the chosen log... function from THIS contract
        // and compare its return value to c.approvedToLog(address(this)). However the requirement asks to relate setApprovedLogger(logger,status) to behavior when called by that logger address.
        // We cannot send calls as arbitrary logger address; but we can at least assert the setter changed the mapping for that logger (observable) whenever setter did not revert.

        // So define two observable consequences:
        // - If setApprovedLogger did not revert, then after == status.
        // - Additionally, for this contract's own approval, we assert that calling a log function returns the same as approvedToLog(address(this)).

        // Call one representative logging function from this contract and capture result/revert
        bool logReverted;
        bool logReturned;
        if (selectorIndex == 0) {
            try c.logFunded() returns (bool r) { logReverted = false; logReturned = r; } catch { logReverted = true; logReturned = false; }
        } else if (selectorIndex == 1) {
            try c.logCreated(address(0x123)) returns (bool r) { logReverted = false; logReturned = r; } catch { logReverted = true; logReturned = false; }
        } else if (selectorIndex == 2) {
            bytes memory outp = new bytes(0);
            bytes memory script = new bytes(0);
            try c.logRedemptionRequested(address(0x123), bytes32(0), uint256(0), script, uint256(0), outp) returns (bool r) { logReverted = false; logReturned = r; } catch { logReverted = true; logReturned = false; }
        } else if (selectorIndex == 3) {
            try c.logGotRedemptionSignature(bytes32(0), bytes32(0), bytes32(0)) returns (bool r) { logReverted = false; logReturned = r; } catch { logReverted = true; logReturned = false; }
        } else {
            try c.logRegisteredPubkey(bytes32(1), bytes32(2)) returns (bool r) { logReverted = false; logReturned = r; } catch { logReverted = true; logReturned = false; }
        }

        bool thisApproved = c.approvedToLog(address(this));

        // General rule (assert):
        // If the setter call did not revert then the mapping for 'logger' was changed to 'status'.
        // Also, calling a logging function from this contract never reverts (logReverted == false), and its returned boolean equals thisApproved.
        assert((setReverted || after == status) && (logReverted == false && logReturned == thisApproved));
    }

    receive() external payable { }
}

